INSERT INTO "Article" ("id", "slug", "category", "country", "titleEn", "titleNe", "excerptEn", "excerptNe", "bodyEn", "bodyNe", "sources", "publishedAt", "createdAt", "updatedAt")
VALUES (
  gen_random_uuid(),
  'un-national-information-officer-unic-kathmandu-20261018',
  'nepal',
  'Nepal',
  'UN Is Hiring a National Information Officer in Kathmandu: Deadline 23 October',
  $$संयुक्त राष्ट्रसंघलाई काठमाडौंमा राष्ट्रिय सूचना अधिकारी चाहियो: म्याद २३ अक्टोबर$$,
  $$The United Nations Information Centre in Kathmandu is hiring a National Information Officer (NO-C). Only candidates with Nepalese nationality can apply, and the deadline is 23 October 2026.$$,
  $$काठमाडौंस्थित संयुक्त राष्ट्रसंघ सूचना केन्द्रलाई राष्ट्रिय सूचना अधिकारी (एनओ–सी) चाहियो। नेपाली नागरिकता भएका उम्मेदवारले मात्र आवेदन दिन पाउँछन्, र म्याद २३ अक्टोबर २०२६ हो।$$,
  $$<p>The United Nations Information Centre (UNIC) in Kathmandu is hiring a National Information Officer, and this one is open only to Nepali nationals. The post sits at the NO-C level in the Department of Global Communications, and the <a href="https://careers.un.org/jobSearchDescription/286168?language=en">official posting</a> shows a deadline of 23 October 2026. Postings on the UN Careers Portal are removed at 11:59 p.m. New York time on the deadline date, so an application left to the last evening in Nepal is already too late.</p><h2>At a glance</h2><table><tr><th>Deadline</th><td>23 October 2026 (removed 11:59 p.m. New York time)</td></tr><tr><th>Posts</th><td>Not stated in the posting</td></tr><tr><th>Location</th><td>Kathmandu, Nepal</td></tr><tr><th>Grade</th><td>National Professional Officer, NO-C</td></tr><tr><th>Eligibility</th><td>Nepalese nationality only; English and Nepali required</td></tr><tr><th>Official channel</th><td>UN Careers, then Inspira</td></tr></table><h2>What the role involves</h2><p>This is the communications job at the heart of how the UN speaks to Nepal. The officer manages contacts and networking with the media, non-governmental organisations, government officials, international and national organisations, business groups and civil society in Nepal. The work includes developing and implementing communications strategies, and handling crisis communications and reputational risk when a story turns difficult. It is a public-facing role in the fullest sense: the person in it shapes what Nepali audiences hear from the United Nations, in English and in Nepali, day after day.</p><p>That matters because the posting treats the two languages as equally required, not as a bonus. Fluency in English and Nepali is a stated requirement, and the day-to-day work runs through Nepali media, Nepali officials and Nepali civil society. A candidate who can write a sharp press line in English and then explain the same point clearly on Nepali radio or television is exactly who this post is built for.</p><h2>Who can apply</h2><p>The Special Notice is unambiguous: only candidates with Nepalese nationality are eligible. Female candidates are strongly encouraged to apply. On education, the posting asks for an advanced university degree, a Master or Doctorate or equivalent, in communications, journalism, public information or a related field. A first-level university degree can stand in its place if it comes with two additional years of qualifying experience.</p><p>On experience, the bar is five years of progressively responsible work, including managing contacts and networking with the media, NGOs, government officials, international and national organisations, business groups and civil society in Nepal. Experience in developing and implementing communications strategies is required, and so is experience in crisis communications or reputational risk management. Desirable extras include speaking to diverse audiences, working across multimedia platforms, and experience with the UN or a comparable international organisation.</p><h2>How to apply</h2><p>Apply through the <a href="https://careers.un.org/jobSearchDescription/286168?language=en">official UN Careers posting for Job Opening 286168</a>. The posting page carries an Apply Now link, and applicants are urged to follow the instructions in the online recruitment platform, Inspira, and to read the Applicant Guide in the Help tile of the Inspira account-holder homepage. The UN charges no fee at any stage of its recruitment. Anyone asking for payment in exchange for this post is running a scam.</p><h2>What to do next</h2><p>Read the full posting before you start, then build your Inspira profile around the two things the posting keeps repeating: media networking in Nepal, and communications strategy plus crisis communications. Give concrete examples with dates, outlets and outcomes, not general claims about being a good communicator. Because the deadline falls at 11:59 p.m. New York time, aim to submit at least a day early in Nepal time, and check that every required document is attached before you press submit. For more Nepal job news, see <a href="/articles?category=nepal">our Nepal coverage</a>.</p>$$,
  $$<p>काठमाडौंस्थित संयुक्त राष्ट्रसंघ सूचना केन्द्र (युनिक) लाई राष्ट्रिय सूचना अधिकारी चाहियो, र यो पद नेपाली नागरिकका लागि मात्र खुला छ। यो पद ग्लोबल कम्युनिकेसन्स विभागमा एनओ–सी तहको हो, र <a href="https://careers.un.org/jobSearchDescription/286168?language=en">आधिकारिक विज्ञापन</a> मा म्याद २३ अक्टोबर २०२६ लेखिएको छ। संयुक्त राष्ट्रसंघको करिअर्स पोर्टलमा विज्ञापनहरू म्यादको दिन न्यूयोर्क समय राति ११:५९ मा हट्छन्, त्यसैले नेपालको समयमा अन्तिम साँझसम्म पर्खेको आवेदन पहिले नै ढिलो भइसक्छ।</p><h2>एक झलकमा</h2><table><tr><th>म्याद</th><td>२३ अक्टोबर २०२६ (न्यूयोर्क समय राति ११:५९ मा हट्छ)</td></tr><tr><th>सिट</th><td>विज्ञापनमा उल्लेख छैन</td></tr><tr><th>स्थान</th><td>काठमाडौं, नेपाल</td></tr><tr><th>तह</th><td>राष्ट्रिय व्यावसायिक अधिकारी, एनओ–सी</td></tr><tr><th>योग्यता</th><td>नेपाली नागरिकता मात्र; अंग्रेजी र नेपाली आवश्यक</td></tr><tr><th>आधिकारिक माध्यम</th><td>यूएन करिअर्स, त्यसपछि इन्स्पिरा</td></tr></table><h2>काम के हो</h2><p>यो राष्ट्रसंघले नेपालसँग कसरी बोल्छ भन्ने कुराको केन्द्रमा रहेको सञ्चारको जागिर हो। अधिकारीले नेपालमा सञ्चारमाध्यम, गैरसरकारी संस्था, सरकारी अधिकारी, अन्तर्राष्ट्रिय तथा राष्ट्रिय संस्था, व्यापारिक समूह र नागरिक समाजसँग सम्पर्क र सञ्जाल व्यवस्थापन गर्छन्। काममा सञ्चार रणनीति बनाउने र लागू गर्ने, र कुनै समाचार कठिन मोडमा पुग्दा संकट सञ्चार तथा प्रतिष्ठाको जोखिम सम्हाल्ने कुरा पर्छ। यो पूर्ण अर्थमा सार्वजनिक अनुहार भएको भूमिका हो: यसमा रहने व्यक्तिले नेपाली श्रोताले संयुक्त राष्ट्रसंघबाट के सुन्छन् भन्ने कुरा अंग्रेजी र नेपाली दुवैमा, दिनदिनै आकार दिन्छन्।</p><p>यो महत्त्वपूर्ण छ किनकि विज्ञापनले दुवै भाषालाई बराबर आवश्यक ठान्छ, थप योग्यता होइन। अंग्रेजी र नेपालीमा धाराप्रवाह हुनु तोकिएको आवश्यकता हो, र दैनिक काम नेपाली सञ्चारमाध्यम, नेपाली अधिकारी र नेपाली नागरिक समाज हुँदै चल्छ। अंग्रेजीमा तीखो प्रेस लाइन लेख्न सक्ने र त्यही कुरा नेपाली रेडियो वा टेलिभिजनमा स्पष्टसँग व्याख्या गर्न सक्ने उम्मेदवार नै यो पदका लागि बनाइएको व्यक्ति हो।</p><h2>कसले आवेदन दिन सक्छ</h2><p>विशेष सूचनामा स्पष्ट छ: नेपाली नागरिकता भएका उम्मेदवार मात्र योग्य छन्। महिला उम्मेदवारलाई विशेष प्रोत्साहन गरिएको छ। शिक्षामा विज्ञापनले सञ्चार, पत्रकारिता, सार्वजनिक सूचना वा सम्बन्धित क्षेत्रमा स्नातकोत्तर (मास्टर्स वा डक्टरेट वा सो सरह) माग्छ। पहिलो तहको विश्वविद्यालयको डिग्रीले पनि हुन्छ, यदि त्यससँग थप दुई वर्षको योग्य अनुभव छ भने।</p><p>अनुभवमा मापदण्ड पाँच वर्षको क्रमशः जिम्मेवार काम हो, जसमा नेपालमा सञ्चारमाध्यम, गैरसरकारी संस्था, सरकारी अधिकारी, अन्तर्राष्ट्रिय तथा राष्ट्रिय संस्था, व्यापारिक समूह र नागरिक समाजसँग सम्पर्क र सञ्जाल व्यवस्थापन गरेको अनुभव पर्छ। सञ्चार रणनीति बनाउने र लागू गरेको अनुभव आवश्यक छ, र संकट सञ्चार वा प्रतिष्ठाको जोखिम व्यवस्थापन गरेको अनुभव पनि आवश्यक छ। थप रुचाइने कुरामा विविध श्रोतालाई सम्बोधन गरेको, मल्टिमिडिया प्लेटफर्ममा काम गरेको, र राष्ट्रसंघ वा सो सरहको अन्तर्राष्ट्रिय संस्थामा काम गरेको अनुभव पर्छ।</p><h2>कसरी आवेदन दिने</h2><p><a href="https://careers.un.org/jobSearchDescription/286168?language=en">जागिर खोल्ने नम्बर २८६१६८ को आधिकारिक यूएन करिअर्स विज्ञापन</a> बाट आवेदन दिनुहोस्। विज्ञापन पृष्ठमा Apply Now लिंक छ, र आवेदकलाई अनलाइन भर्ती प्लेटफर्म इन्स्पिरामा भएका सबै निर्देशन पालना गर्न र इन्स्पिरा खातावालाको होमपेजमा Help टाइलभित्र Manuals मा गएर आवेदक निर्देशिका पढ्न आग्रह गरिएको छ। राष्ट्रसंघले आफ्नो भर्नाको कुनै पनि चरणमा शुल्क लिँदैन। यो पदको साटो पैसा माग्ने जो कोही ठगी चलाइरहेको हुन्छ।</p><h2>अब के गर्ने</h2><p>सुरु गर्नुअघि पूरै विज्ञापन पढ्नुहोस्, त्यसपछि विज्ञापनले बारम्बार दोहोर्‍याउने दुई कुरामा आफ्नो इन्स्पिरा प्रोफाइल बनाउनुहोस्: नेपालमा सञ्चारमाध्यमसँगको सञ्जाल, र सञ्चार रणनीति तथा संकट सञ्चार। राम्रो सञ्चारक हुँ भन्ने सामान्य दाबी होइन, मिति, सञ्चारमाध्यम र परिणामसहित ठोस उदाहरण दिनुहोस्। म्याद न्यूयोर्क समय राति ११:५९ मा सकिने भएकाले नेपालको समयमा कम्तीमा एक दिन अगाडि नै बुझाउने लक्ष्य राख्नुहोस्, र बुझाउनुअघि सबै आवश्यक कागजात संलग्न भएको जाँच्नुहोस्। नेपालका थप जागिर समाचारका लागि <a href="/articles?category=nepal">हाम्रो नेपाल कभरेज</a> हेर्नुहोस्।</p>$$,
  ARRAY['https://careers.un.org/jobSearchDescription/286168?language=en']::text[],
  NOW(), NOW(), NOW()),
(
  gen_random_uuid(),
  'unocha-humanitarian-affairs-officer-rasuwa-20261018',
  'nepal',
  'Nepal',
  'UNOCHA Seeks Humanitarian Affairs Officer for Flood-Hit Rasuwa: Apply Before 25 October',
  $$ओसीएचएलाई बाढी प्रभावित रसुवाका लागि मानवीय मामिला अधिकारी चाहियो: २५ अक्टोबरअघि आवेदन दिनुहोस्$$,
  $$UNOCHA is hiring a Humanitarian Affairs Officer (NOB, temporary 4 months) based in Rasuwa, to coordinate the flood response across Rasuwa and Nuwakot. Apply before 25 October 2026, 23:59 — the posting states no timezone.$$,
  $$ओसीएचएलाई रसुवामा आधारित मानवीय मामिला अधिकारी (एनओबी, अस्थायी ४ महिना) चाहियो, जसले रसुवा र नुवाकोटमा बाढी प्रतिकार्यको समन्वय गर्नेछन्। २५ अक्टोबर २०२६, २३:५९ अघि आवेदन दिनुहोस् — विज्ञापनमा समय क्षेत्र उल्लेख छैन।$$,
  $$<p>The floods that hit Rasuwa need coordination on the ground, and that is exactly what this post is for. The United Nations Office for the Coordination of Humanitarian Affairs (OCHA) is hiring a Humanitarian Affairs Officer, based in Rasuwa, to support the humanitarian response to the floods affecting Rasuwa and surrounding areas. The <a href="https://estm.fa.em2.oraclecloud.com/hcmUI/CandidateExperience/en/sites/CX_1/job/37495">official UNDP Careers posting</a> reads "Apply Before 25/10/2026, 23:59", with no timezone stated. The number of posts is not stated: the posting says UNDP reserves the right to select one or more candidates.</p><h2>At a glance</h2><table><tr><th>Deadline</th><td>25 October 2026, 23:59 (no timezone stated)</td></tr><tr><th>Posts</th><td>Not stated — one or more may be selected</td></tr><tr><th>Location</th><td>Rasuwa, Nepal (field work also in Nuwakot)</td></tr><tr><th>Grade and contract</th><td>NOB, temporary, 4 months, full time</td></tr><tr><th>Eligibility</th><td>Master degree + 2 years, or Bachelor degree + 4 years; excellent Nepali and English</td></tr><tr><th>Official channel</th><td>UNDP Careers posting</td></tr></table><h2>What the role involves</h2><p>This is field coordination work, not a desk job in Kathmandu. The officer works under the RCO/OCHA Bidur Hub lead, with a particular focus on Rasuwa and Nuwakot, supporting field-level coordination, assessments and reporting for the flood response, along with accountability to affected people and protection from sexual exploitation and abuse (AAP/PSEA). In practice that means being the person who knows what each actor is doing in the affected areas, where the gaps are, and what the affected communities themselves are saying they need.</p><p>The timing explains the shape of the post. A four-month temporary contract is a response contract: it exists because the floods happened, and it ends when the acute phase winds down. Anyone applying should be ready to deploy to Rasuwa quickly, to work in field conditions, and to produce clear, honest reporting under pressure. That is the real test of this role, and it is worth weighing before applying.</p><h2>Who can apply</h2><p>The posting asks for an advanced university degree, a Master or equivalent, in humanitarian affairs, environmental science, social science, climate change, international development, business administration, public administration or a related field. A first-level university degree, a Bachelor or equivalent, in the same fields is accepted with two additional years of relevant experience.</p><p>On experience, the minimum is two years with a Master degree or four years with a Bachelor degree, of relevant work at national or international level in disaster management, humanitarian work or a related thematic area. Relevant experience with a UN agency or a comparable humanitarian organisation is required, and so is experience in crisis or emergency relief management and humanitarian or emergency field coordination. Excellent oral and written command of Nepali and English is required.</p><h2>How to apply</h2><p>Apply only through the <a href="https://estm.fa.em2.oraclecloud.com/hcmUI/CandidateExperience/en/sites/CX_1/job/37495">official UNDP Careers posting for Job ID 37495</a>, which carries an Apply Now button. A UNDP Careers account is needed to submit. The UN charges no application fee at any stage. Anyone asking for payment in exchange for this post is running a scam.</p><h2>What to do next</h2><p>Because the posting leaves the timezone of the 23:59 cutoff unstated, do not cut it fine: submit well before the evening of 25 October in Nepal time. In your application, lead with field coordination experience in disaster or emergency settings, and give concrete examples of assessments, coordination meetings and reporting you have actually done. Vague claims about caring for affected people carry no weight here; dated, specific field experience does. For more Nepal job news, see <a href="/articles?category=nepal">our Nepal coverage</a>.</p>$$,
  $$<p>रसुवामा आएको बाढीका लागि जमिनमै समन्वय चाहिन्छ, र यो पद ठ्याक्कै त्यसैका लागि हो। मानवीय मामिला समन्वयका लागि संयुक्त राष्ट्रसंघीय कार्यालय (ओचा) लाई रसुवामा आधारित मानवीय मामिला अधिकारी चाहियो, जसले रसुवा र वरपरका क्षेत्रमा बाढीले असर पारेको मानवीय प्रतिकार्यमा सहयोग गर्नेछन्। <a href="https://estm.fa.em2.oraclecloud.com/hcmUI/CandidateExperience/en/sites/CX_1/job/37495">आधिकारिक यूएनडीपी करिअर्स विज्ञापन</a> मा "Apply Before 25/10/2026, 23:59" लेखिएको छ, समय क्षेत्र उल्लेख छैन। सिट संख्या उल्लेख छैन: विज्ञापनमा यूएनडीपीले एक वा बढी उम्मेदवार छान्न सक्ने अधिकार सुरक्षित राखेको लेखिएको छ।</p><h2>एक झलकमा</h2><table><tr><th>म्याद</th><td>२५ अक्टोबर २०२६, २३:५९ (समय क्षेत्र उल्लेख छैन)</td></tr><tr><th>सिट</th><td>उल्लेख छैन — एक वा बढी छानिन सक्छन्</td></tr><tr><th>स्थान</th><td>रसुवा, नेपाल (फिल्ड काम नुवाकोटमा पनि)</td></tr><tr><th>तह र करार</th><td>एनओबी, अस्थायी, ४ महिना, पूर्णकालीन</td></tr><tr><th>योग्यता</th><td>मास्टर्स + २ वर्ष, वा ब्याचलर + ४ वर्ष; नेपाली र अंग्रेजीमा उत्कृष्ट</td></tr><tr><th>आधिकारिक माध्यम</th><td>यूएनडीपी करिअर्स विज्ञापन</td></tr></table><h2>काम के हो</h2><p>यो काठमाडौंमा डेस्कमा बस्ने जागिर होइन, फिल्ड समन्वयको काम हो। अधिकारीले आरसीओ/ओचा बिदुर हब प्रमुख मातहत काम गर्छन्, विशेष ध्यान रसुवा र नुवाकोटमा राख्दै, बाढी प्रतिकार्यका लागि फिल्ड तहको समन्वय, मूल्यांकन र प्रतिवेदनमा सहयोग गर्छन्, साथै प्रभावित मानिसप्रतिको जवाफदेहिता र यौन शोषण तथा दुव्र्यवहारबाट सुरक्षा (एएपी/पीएसईए) को काम पनि हुन्छ। व्यवहारमा यसको अर्थ प्रभावित क्षेत्रमा प्रत्येक निकायले के गरिरहेको छ, कहाँ कमी छ, र प्रभावित समुदाय आफैंले के चाहिन्छ भनिरहेका छन् भन्ने कुरा जान्ने व्यक्ति हुनु हो।</p><p>समयले नै यो पदको आकार व्याख्या गर्छ। चार महिनाको अस्थायी करार प्रतिकार्य करार हो: यो बाढी आएको कारणले छ, र तीव्र चरण सकिएपछि सकिन्छ। आवेदन दिने जो कोही रसुवामा छिटो खटिन, फिल्ड अवस्थामा काम गर्न, र दबाबमा स्पष्ट, इमानदार प्रतिवेदन बनाउन तयार हुनुपर्छ। यही यस भूमिकाको वास्तविक परीक्षा हो, र आवेदन दिनुअघि यसबारे सोच्नु उपयुक्त हुन्छ।</p><h2>कसले आवेदन दिन सक्छ</h2><p>विज्ञापनले मानवीय मामिला, वातावरण विज्ञान, सामाजिक विज्ञान, जलवायु परिवर्तन, अन्तर्राष्ट्रिय विकास, व्यापार प्रशासन, सार्वजनिक प्रशासन वा सम्बन्धित क्षेत्रमा स्नातकोत्तर (मास्टर्स वा सो सरह) माग्छ। सोही क्षेत्रमा पहिलो तहको विश्वविद्यालयको डिग्री (ब्याचलर वा सो सरह) लाई पनि थप दुई वर्षको सान्दर्भिक अनुभवसहित मानिन्छ।</p><p>अनुभवमा न्यूनतम मापदण्ड मास्टर्ससहित दुई वर्ष वा ब्याचलरसहित चार वर्षको विपद् व्यवस्थापन, मानवीय कार्य वा सम्बन्धित विषय क्षेत्रमा राष्ट्रिय वा अन्तर्राष्ट्रिय तहको सान्दर्भिक काम हो। राष्ट्रसंघीय निकाय वा सो सरहको मानवीय संस्थासँगको सान्दर्भिक अनुभव आवश्यक छ, र संकट वा आपतकालीन राहत व्यवस्थापन तथा मानवीय वा आपतकालीन फिल्ड समन्वयको अनुभव पनि आवश्यक छ। नेपाली र अंग्रेजीमा उत्कृष्ट मौखिक तथा लिखित पकड आवश्यक छ।</p><h2>कसरी आवेदन दिने</h2><p><a href="https://estm.fa.em2.oraclecloud.com/hcmUI/CandidateExperience/en/sites/CX_1/job/37495">जागिर आईडी ३७४९५ को आधिकारिक यूएनडीपी करिअर्स विज्ञापन</a> बाट मात्र आवेदन दिनुहोस्, जसमा Apply Now बटन छ। बुझाउन यूएनडीपी करिअर्स खाता चाहिन्छ। राष्ट्रसंघले आफ्नो भर्नाको कुनै पनि चरणमा शुल्क लिँदैन। यो पदको साटो पैसा माग्ने जो कोही ठगी चलाइरहेको हुन्छ।</p><h2>अब के गर्ने</h2><p>२३:५९ को कटअफको समय क्षेत्र विज्ञापनमा उल्लेख नभएकाले अन्तिम क्षणसम्म नपर्खनुहोस्: नेपालको समयमा २५ अक्टोबरको साँझभन्दा धेरै अगाडि नै बुझाउनुहोस्। आवेदनमा विपद् वा आपतकालीन अवस्थामा फिल्ड समन्वयको अनुभवलाई अगाडि राख्नुहोस्, र तपाईंले वास्तवमै गर्नुभएका मूल्यांकन, समन्वय बैठक र प्रतिवेदनका ठोस उदाहरण दिनुहोस्। प्रभावित मानिसको चिन्ता छ भन्ने अस्पष्ट दाबीले यहाँ कुनै अर्थ राख्दैन; मितिसहितको विशिष्ट फिल्ड अनुभवले राख्छ। नेपालका थप जागिर समाचारका लागि <a href="/articles?category=nepal">हाम्रो नेपाल कभरेज</a> हेर्नुहोस्।</p>$$,
  ARRAY['https://estm.fa.em2.oraclecloud.com/hcmUI/CandidateExperience/en/sites/CX_1/job/37495']::text[],
  NOW(), NOW(), NOW()),
(
  gen_random_uuid(),
  'phase-nepal-14-jobs-community-health-20261018',
  'nepal',
  'Nepal',
  'PHASE Nepal Is Hiring 14 Staff for a UNICEF-Partner Health Project: Deadline 27 October',
  $$फेज नेपाललाई युनिसेफ साझेदार स्वास्थ्य परियोजनाका लागि १४ कर्मचारी चाहियो: म्याद २७ अक्टोबर$$,
  $$PHASE Nepal is hiring 14 staff for its Strengthening Community Health Systems project with UNICEF Nepal, across Karnali and Madhesh provinces. Gross salaries run NPR 57,263–99,605 a month, and applications close 27 October 2026 — though the notice says it may close early if a suitable candidate is found.$$,
  $$फेज नेपाललाई युनिसेफ नेपालसँगको समुदाय स्वास्थ्य प्रणाली सुदृढीकरण परियोजनाका लागि कर्णाली र मधेश प्रदेशमा १४ कर्मचारी चाहियो। कूल तलब मासिक ५७,२६३–९९,६०५ रुपैयाँ छ, र आवेदन २७ अक्टोबर २०२६ मा बन्द हुन्छ — यद्यपि सूचनामा उपयुक्त उम्मेदवार भेटिए म्यादअघि नै बन्द हुन सक्ने लेखिएको छ।$$,
  $$<p>Fourteen field posts, one project, two provinces. PHASE Nepal is hiring for its Strengthening Community Health Systems project, run in partnership with UNICEF Nepal from September 2026 to December 2027, across Karnali and Madhesh provinces. The <a href="https://phasenepal.org/vacancy/">official vacancy notice</a> asks interested candidates to apply by filling in the online form no later than 27 October 2026, and it adds a warning worth heeding: the organisation is urgently looking, and it will close applications early if it finds an appropriate candidate before the deadline. Apply as soon as possible if you are interested.</p><h2>At a glance</h2><table><tr><th>Deadline</th><td>27 October 2026 — may close early if a suitable candidate is found</td></tr><tr><th>Posts</th><td>14 (Field Coordinator 1, KM and SBCC Officer 1, Field Officer 6, Community Mobiliser ANM 6)</td></tr><tr><th>Location</th><td>Karnali and Madhesh provinces</td></tr><tr><th>Salary</th><td>Gross NPR 57,263–99,605 per month, by role and municipality</td></tr><tr><th>Official channel</th><td>PHASE Nepal vacancy notice, online form only</td></tr></table><h2>The 14 posts</h2><p>The largest groups are the field posts. Six Field Officers are split evenly between the provinces: three in Karnali (Bheri, Sani Bheri and Birendranagar, one each) and three in Madhesh (Hanumannagar Kankalini, Kolhabi and Birgunj Metro, one each). Six Community Mobilisers (ANM) follow the same split across the same six municipalities. Above them sit two single posts: a Field Coordinator in Birgunj/Parsa, and a Knowledge Management and SBCC Officer in Surkhet. Priority goes to local applicants, which matters for anyone deciding where to apply from.</p><p>Pay is stated plainly in the notice, as gross monthly figures that include the Social Security Fund, Dashain Allowance, Food and Field Allowance and Project Allowance, subject to statutory tax deductions. The Field Coordinator and the Knowledge Management and SBCC Officer both sit at NPR 99,605. Field Officers in Karnali earn NPR 71,436, 71,436 or 68,731 depending on municipality, and NPR 66,731 for all three Madhesh posts. Community Mobilisers (ANM) in Karnali earn NPR 61,968, 61,968 or 59,263, and NPR 57,263 for all three Madhesh posts. The notice also provides accidental insurance of NPR 20,00,000 per employee and medical insurance of NPR 2,25,000 for the employee and eligible dependents.</p><h2>Who can apply</h2><p>For the Field Coordinator post, the notice asks for a Master of Public Health with four to five years of experience. For the remaining roles, read the full criteria on the official notice for the exact post you want before applying: the notice sets out the requirements post by post, and applying against the wrong criteria wastes a strong application. As the title says, the Community Mobiliser posts are ANM roles. One condition applies to everyone: no telephone inquiries will be entertained, and any inappropriate recommendation will automatically disqualify the candidate.</p><h2>How to apply</h2><p>Apply only through the online form linked from the <a href="https://phasenepal.org/vacancy/">official PHASE Nepal vacancy notice</a>. The notice states no email or postal route. Because early closure is explicitly on the table, the sensible move is to apply now rather than to polish an application until the deadline week. Read the post you want, gather your documents, and submit through the form.</p><h2>What to do next</h2><p>Choose the municipality you can genuinely serve — local applicants get priority, and a field post is a field post, not a desk in Birgunj or Surkhet. Then apply through the official form and keep a copy of your submission. For more Nepal job news, see <a href="/articles?category=nepal">our Nepal coverage</a>.</p>$$,
  $$<p>चौधवटा फिल्ड पद, एउटा परियोजना, दुई प्रदेश। फेज नेपालले युनिसेफ नेपालसँगको साझेदारीमा सेप्टेम्बर २०२६ देखि डिसेम्बर २०२७ सम्म चल्ने समुदाय स्वास्थ्य प्रणाली सुदृढीकरण परियोजनाका लागि कर्णाली र मधेश प्रदेशमा कर्मचारी भर्ना गर्दैछ। <a href="https://phasenepal.org/vacancy/">आधिकारिक रिक्ति सूचना</a> मा इच्छुक उम्मेदवारलाई २७ अक्टोबर २०२६ भन्दा ढिलो नहुने गरी अनलाइन फारम भरेर आवेदन दिन भनिएको छ, र ध्यान दिनुपर्ने चेतावनी पनि छ: संस्थालाई तत्काल आवश्यकता छ, र म्यादअघि उपयुक्त उम्मेदवार भेटिए आवेदन चाँडै बन्द गर्नेछ। इच्छुक भए जति सक्दो चाँडो आवेदन दिनुहोस्।</p><h2>एक झलकमा</h2><table><tr><th>म्याद</th><td>२७ अक्टोबर २०२६ — उपयुक्त उम्मेदवार भेटिए चाँडै बन्द हुन सक्छ</td></tr><tr><th>सिट</th><td>१४ (फिल्ड संयोजक १, केएम तथा एसबीसीसी अधिकारी १, फिल्ड अधिकारी ६, समुदाय परिचालक एएनएम ६)</td></tr><tr><th>स्थान</th><td>कर्णाली र मधेश प्रदेश</td></tr><tr><th>तलब</th><td>कूल मासिक ५७,२६३–९९,६०५ रुपैयाँ, भूमिका र पालिकाअनुसार</td></tr><tr><th>आधिकारिक माध्यम</th><td>फेज नेपाल रिक्ति सूचना, अनलाइन फारम मात्र</td></tr></table><h2>१४ पद</h2><p>सबैभन्दा ठूला समूह फिल्ड पद हुन्। छ फिल्ड अधिकारी दुवै प्रदेशमा बराबर बाँडिएका छन्: कर्णालीमा तीन (भेरी, सानीभेरी र वीरेन्द्रनगर, प्रत्येकमा एक–एक) र मधेशमा तीन (हनुमाननगर कंकालिनी, कोल्हबी र वीरगञ्ज महानगर, प्रत्येकमा एक–एक)। छ समुदाय परिचालक (एएनएम) पनि त्यही विभाजनमा त्यही छ पालिकामा छन्। तिनभन्दा माथि दुई एकल पद छन्: वीरगञ्ज/पर्सामा फिल्ड संयोजक, र सुर्खेतमा ज्ञान व्यवस्थापन तथा एसबीसीसी अधिकारी। स्थानीय आवेदकलाई प्राथमिकता दिइन्छ, जुन कहाँबाट आवेदन दिने भन्ने निर्णय गर्ने जो कोहीका लागि महत्त्वपूर्ण छ।</p><p>तलब सूचनामा स्पष्टसँग उल्लेख छ, कूल मासिक अंकका रूपमा, जसमा सामाजिक सुरक्षा कोष, दसैं भत्ता, खाना तथा फिल्ड भत्ता र परियोजना भत्ता समावेश छन्, वैधानिक कर कट्टीको अधीनमा। फिल्ड संयोजक र ज्ञान व्यवस्थापन तथा एसबीसीसी अधिकारी दुवैको ९९,६०५ रुपैयाँ छ। कर्णालीमा फिल्ड अधिकारीको ७१,४३६, ७१,४३६ वा ६८,७३१ रुपैयाँ पालिकाअनुसार छ, र मधेशका तीनै पदको ६६,७३१ रुपैयाँ छ। कर्णालीमा समुदाय परिचालक (एएनएम) को ६१,९६८, ६१,९६८ वा ५९,२६३ रुपैयाँ, र मधेशका तीनै पदको ५७,२६३ रुपैयाँ छ। सूचनाले प्रति कर्मचारी २०,००,००० रुपैयाँको दुर्घटना बीमा र कर्मचारी तथा योग्य आश्रितका लागि २,२५,००० रुपैयाँको स्वास्थ्य बीमा पनि दिन्छ।</p><h2>कसले आवेदन दिन सक्छ</h2><p>फिल्ड संयोजक पदका लागि सूचनाले चारदेखि पाँच वर्षको अनुभवसहित जनस्वास्थ्यमा स्नातकोत्तर (एमपीएच) माग्छ। बाँकी भूमिकाका लागि आवेदन दिनुअघि तपाईंले चाहेको ठ्याक्कै पदको पूरा मापदण्ड आधिकारिक सूचनामा पढ्नुहोस्: सूचनाले मापदण्ड पद–पदअनुसार दिएको छ, र गलत मापदण्डमा आवेदन दिनुले राम्रो आवेदन खेर जान्छ। शीर्षकले भनेझैं समुदाय परिचालक पद एएनएम भूमिका हुन्। सबैमा लागू हुने एउटा शर्त छ: टेलिफोन सोधपुछ गरिने छैन, र कुनै अनुचित सिफारिसले उम्मेदवारलाई स्वतः अयोग्य बनाउँछ।</p><h2>कसरी आवेदन दिने</h2><p><a href="https://phasenepal.org/vacancy/">आधिकारिक फेज नेपाल रिक्ति सूचना</a> बाट लिंक गरिएको अनलाइन फारमबाट मात्र आवेदन दिनुहोस्। सूचनामा इमेल वा हुलाक माध्यम उल्लेख छैन। चाँडै बन्द हुने कुरा स्पष्ट रूपमा उल्लेख भएकाले बुद्धिमानी चाल म्यादको सातासम्म आवेदन चम्काउन पर्खनु होइन, अहिले नै आवेदन दिनु हो। तपाईंले चाहेको पद पढ्नुहोस्, कागजात जम्मा गर्नुहोस्, र फारमबाट बुझाउनुहोस्।</p><h2>अब के गर्ने</h2><p>तपाईंले साँच्चै सेवा गर्न सक्ने पालिका छान्नुहोस् — स्थानीय आवेदकलाई प्राथमिकता छ, र फिल्ड पद फिल्ड पद नै हो, वीरगञ्ज वा सुर्खेतमा डेस्क होइन। त्यसपछि आधिकारिक फारमबाट आवेदन दिनुहोस् र बुझाएको प्रतिलिपि राख्नुहोस्। नेपालका थप जागिर समाचारका लागि <a href="/articles?category=nepal">हाम्रो नेपाल कभरेज</a> हेर्नुहोस्।</p>$$,
  ARRAY['https://phasenepal.org/vacancy/']::text[],
  NOW(), NOW(), NOW())
ON CONFLICT (slug) DO NOTHING;
